const visualCropButton=document.createElement('button');visualCropButton.id='openVisualCrop';visualCropButton.type='button';visualCropButton.className='solid-btn';visualCropButton.textContent='Pan/Crop · editor visual';$('#openEventWork').after(visualCropButton);
